def _(FT, np, plt, rd_run, rd_scn):
    _runs = FT["runs"][rd_scn.value]
    _i = min(rd_run.value, len(_runs["trl"]) - 1, len(_runs["unsloth"]) - 1)
    _t, _u = _runs["trl"][_i], _runs["unsloth"][_i]
    _fig, (_a1, _a2) = plt.subplots(2, 1, figsize=(6.4, 5.8), sharex=True)
    _x = np.arange(1, len(_t["loss"]) + 1)
    _a1.plot(_x, _t["loss"], color="#4C72B0", lw=2.2, label="TRL + PEFT (trl 1.13)")
    _a1.plot(_x, _u["loss"], color="#DD8452", lw=2.2, ls="--", label="Unsloth 2026.9.11")
    _a1.set_yscale("log")
    _a1.set_ylabel("training loss (log)")
    _a1.set_title("same data, same hyper-parameters: the curves almost overlap")
    _a1.legend(frameon=False)
    _a1.grid(alpha=0.3)
    _a2.plot(_x, _t["step_s"], color="#4C72B0", lw=1.8, label="TRL + PEFT")
    _a2.plot(_x, _u["step_s"], color="#DD8452", lw=1.8, ls="--", label="Unsloth")
    _a2.set_ylabel("seconds per step")
    _a2.set_xlabel("training step")
    _a2.set_ylim(0, max(max(_t["step_s"]), max(_u["step_s"])) * 1.1)
    _a2.grid(alpha=0.3)
    _fig.tight_layout()
    _fig
    return


@app.cell
def _(FT, mo, np, rd_run, rd_scn):
    _runs = FT["runs"][rd_scn.value]
    _i = min(rd_run.value, len(_runs["trl"]) - 1, len(_runs["unsloth"]) - 1)
    _t, _u = _runs["trl"][_i], _runs["unsloth"][_i]

    def _med(r):
        return float(np.median(r["step_s"][3:]))

    _all_ratio = [float(np.median(a["step_s"][3:]) / np.median(b["step_s"][3:]))
                  for a, b in zip(_runs["trl"], _runs["unsloth"], strict=False)]
    mo.md(
        f"""
    | 這次實測 | TRL＋PEFT | Unsloth | 比一比 |
    | --- | ---: | ---: | --- |
    | 60 步總秒數 | {_t['train_s']:.1f} s | {_u['train_s']:.1f} s | Unsloth 第 1 步含暖機 {_u['step_s'][0]:.1f} s |
    | 每步秒數（中位數） | {_med(_t):.2f} s | {_med(_u):.2f} s | TRL ÷ Unsloth ＝ **{_med(_t) / _med(_u):.1f} 倍** |
    | 峰值 VRAM（PyTorch reserved） | {_t['peak']:.2f} GiB | {_u['peak']:.2f} GiB | 少 **{(1 - _u['peak'] / _t['peak']) * 100:.0f}%** |
    | 載入 4-bit 權重後 | {_t['load']:.2f} GiB | {_u['load']:.2f} GiB | 同一份權重 |
    | 最後一步 loss | {_t['loss'][-1]:.4f} | {_u['loss'][-1]:.4f} | 學到同一件事 |

    秒數曲線上突然的跳動（例如長資料第 1 次，Unsloth 在第 40 步附近變慢、TRL 在第 46 步附近變快）
    是主機上其他服務的負載在變——兩次訓練不是同時跑的。

    這個情境跑了 {len(_all_ratio)} 次，「每步快幾倍」依序是
    {"、".join(f"{r:.1f}" for r in _all_ratio)} 倍——**時間會飄**：這張 4090 同時有別的服務在用
    （GPU 使用率約 45%），所以秒數只看比例與量級；**峰值 VRAM 每次幾乎一樣**（差不到 0.01 GiB），那是確定的。
    """
    )
    return


