@app.cell
def _(CATS, KEYS, html_mod, json, mo, ta_line):
    _lines = [ln for ln in ta_line.value.splitlines() if ln.strip()]
    _checks, _render = [], []
    _ROLES = {"system", "user", "assistant"}
    for _n, _ln in enumerate(_lines[:5], 1):
        _tag = f"第 {_n} 行" if len(_lines) > 1 else "這一行"
        try:
            _obj = json.loads(_ln)
        except json.JSONDecodeError as _e:
            _checks.append(("err", f"{_tag}不是合法 JSON：`{_e.msg}`（第 {_e.colno} 個字）——JSON 字串要用雙引號"))
            continue
        _msgs = _obj.get("messages") if isinstance(_obj, dict) else None
        if not isinstance(_msgs, list):
            _keys = "、".join(_obj) if isinstance(_obj, dict) else type(_obj).__name__
            _checks.append(("err", (f"{_tag}沒有 `messages` 清單（看到的欄位：{_keys}）——"
                                    "舊的 instruction／output 格式要先轉成 messages")))
            continue
        _bad = [m for m in _msgs if not isinstance(m, dict) or m.get("role") not in _ROLES
                or not isinstance(m.get("content"), str)]
        if _bad:
            _checks.append(("err", (f"{_tag}有 {len(_bad)} 則訊息的 role 不在 system／user／assistant 之內"
                                    f"（看到 `{_bad[0].get('role') if isinstance(_bad[0], dict) else _bad[0]}`）")))
            continue
        if not _msgs or _msgs[-1]["role"] != "assistant":
            _checks.append(("err", f"{_tag}最後一則不是 assistant——沒有「標準答案」，模型沒東西可學"))
            continue
        _body = [m["role"] for m in _msgs if m["role"] != "system"]
        if any(_body[i] == _body[i + 1] for i in range(len(_body) - 1)):
            _checks.append(("warn", f"{_tag}有連續兩則同一個 role——多數 chat template 預期 user／assistant 輪流"))
        if _msgs[0]["role"] != "system":
            _checks.append(("warn", f"{_tag}沒有 system——可以，但推論時也要用一樣的開頭，訓練與推論才對得上"))
        try:
            _ans = json.loads(_msgs[-1]["content"])
            if sorted(_ans) != sorted(KEYS) or _ans.get("category") not in CATS:
                _checks.append(("warn", f"{_tag}的回答是 JSON，但欄位或類別跟本課任務的 schema 不一致"))
            else:
                _checks.append(("ok", f"{_tag}格式正確，回答符合本課任務的 schema"))
        except (json.JSONDecodeError, AttributeError, TypeError):
            _checks.append(("err", f"{_tag}的回答不是合法 JSON——本課任務要模型只輸出 JSON，示範資料就得先做到"))
        # 套上 Qwen3 chat template（與實測時 TRL 資料整理器吐出來的 labels 同一套切法）
        _parts = []
        _last_a = max(i for i, m in enumerate(_msgs) if m["role"] == "assistant")
        for _k, _m in enumerate(_msgs):
            if _m["role"] == "assistant":
                _parts.append((False, "<|im_start|>assistant\n"))
                _think = "<think>\n\n</think>\n\n" if _k == _last_a else ""
                _parts.append((True, _think + _m["content"] + "<|im_end|>"))
                _parts.append((False, "\n"))
            else:
                _parts.append((False, f"<|im_start|>{_m['role']}\n{_m['content']}<|im_end|>\n"))
        _render.append(_parts)

    _icon = {"ok": ("✅", "#2E7042"), "warn": ("⚠️", "#B36B00"), "err": ("❌", "#C44E52")}
    _ck = "".join(f'<div style="color:{_icon[k][1]};font-size:13px;margin:2px 0">{_icon[k][0]} {html_mod.escape(t)}</div>'
                  for k, t in _checks) or '<div style="font-size:13px">（框裡是空的）</div>'
    _rd = ""
    for _parts in _render:
        _n_loss = sum(len(t) for on, t in _parts if on)
        _n_all = sum(len(t) for _, t in _parts)
        _spans = "".join(
            f'<span style="background:{"#E4F2E7" if on else "#EEF0F2"};color:{"#1E5C30" if on else "#7A8791"};'
            f'{"font-weight:700;" if on else ""}">{html_mod.escape(t)}</span>' for on, t in _parts)
        _rd += (f'<div style="font-family:ui-monospace,monospace;font-size:12px;line-height:1.7;white-space:pre-wrap;'
                f'word-break:break-word;border:1px solid #D5DBDF;border-radius:10px;padding:10px 12px;margin-top:8px">{_spans}</div>'
                f'<div style="font-size:12px;color:#5A6A72;margin-top:4px">灰＝模型看得到、但<b>不算 loss</b>；綠＝要學會寫出來的字'
                f'（{_n_loss} / {_n_all} 個字元，約 {_n_loss / _n_all:.0%}）</div>')
    mo.Html(_ck + _rd)
    return


